<template><div><div class="summary-grid"><div v-for="m in metrics" :key="m.key" class="summary-card"><div class="eyebrow">{{$t(m.label)}}</div><span :class="['number',{emphasis:m.key==='waiting'||m.key==='unpaid'}]">{{$t(numbers[m.key]||0)}}</span></div></div><section class="panel"><div class="panel-title"><h2>{{$t("常用操作")}}</h2><el-button size="small" icon="el-icon-refresh" @click="load">{{$t("刷新数据")}}</el-button></div><div class="actions"><el-button v-for="item in quick" :key="item.to" @click="$emit('goto',item.to)">{{$t(item.label)}} <i class="el-icon-arrow-right"/></el-button></div></section><section class="panel"><div class="panel-title"><h2>{{$t("业务提醒")}}</h2></div><ol class="business-reminders">
<li><span>{{$t('患者资料用于仿真业务演示，请勿录入真实个人信息。')}}</span></li>
<li v-if="loaded"><div class="reminder-content"><span>{{$t('今日还有 {count} 位患者等待接诊，请及时查看就诊队列。',{count:numbers.waiting||0})}}</span><el-button v-if="canOpen('medical')" type="text" @click="$emit('goto','medical')">{{$t('查看接诊队列')}}</el-button><el-button v-else-if="canOpen('registrations')" type="text" @click="$emit('goto','registrations')">{{$t('查看挂号记录')}}</el-button></div></li>
<li v-if="loaded"><div class="reminder-content"><span>{{$t('当前有 {unpaid} 项费用待收取、{prescriptions} 项药品待发放，请核对缴费与发药状态。',{unpaid:numbers.unpaid||0,prescriptions:numbers.prescriptions||0})}}</span><div class="reminder-actions"><el-button v-if="canOpen('billing')" type="text" @click="$emit('goto','billing')">{{$t('查看待收费项目')}}</el-button><el-button v-if="canOpen('pharmacy')" type="text" @click="$emit('goto','pharmacy')">{{$t('查看待发药品')}}</el-button></div></div></li>
</ol><p v-if="!loaded" class="muted">{{$t('正在获取业务提醒…')}}</p></section></div></template>
<script>import api from '../api';export default{name:'Dashboard',props:['user'],data(){return{numbers:{},loaded:false,metrics:[{key:'visits',label:'今日有效挂号'},{key:'waiting',label:'等待接诊'},{key:'unpaid',label:'待收费项目'},{key:'completed',label:'今日诊毕'}]}},computed:{quick(){const r=this.user.role;return[{to:'registrations',label:'办理挂号',roles:['ADMIN','REGISTRAR']},{to:'medical',label:'进入医生工作台',roles:['ADMIN','DOCTOR']},{to:'check',label:'检查队列',roles:['ADMIN','EXAM','DOCTOR']},{to:'lab',label:'检验队列',roles:['ADMIN','LAB','DOCTOR']},{to:'procedure',label:'处置队列',roles:['ADMIN','PROCEDURE','DOCTOR']},{to:'pharmacy',label:'药房发药',roles:['ADMIN','PHARMACIST']},{to:'billing',label:'待收费查询',roles:['ADMIN','REGISTRAR','DOCTOR']}].filter(x=>x.roles.includes(r))}},created(){this.load()},methods:{canOpen(page){return this.quick.some(item=>item.to===page)},async load(){try{this.numbers=await api.get('/dashboard');this.loaded=true}catch(e){this.$message.error(e.message)}}}}</script>
